const rateProfiles = rateDefinitions.map(([id, basis, nurturing, destruction, notes]) => ({
  id, basis, nurturing, destruction, notes, status: 'Initial balance values; not runtime rates'
}));
const rateProfileById = new Map(rateProfiles.map(profile => [profile.id, profile]));
function rateCells(id) {
  const profile = rateProfileById.get(id);
  if (!profile) throw Error(`Missing numeric ecological rate profile: ${id}`);
  return rateLedgers.flatMap((_, index) => [profile.nurturing[index], profile.destruction[index]]);
}

// Design contract only. These policies do not add a runtime planner.
const monthlyEcology = {
  planningCadence: 'oncePerGameMonth',
  application: 'gradualEventBoundedAccrual',
  rateUnit: 'ecologicalPointsPerIndividualPerGameDayPerLedger',
  pointDefinition: 'One ecological point changes one hectare of affected habitat by one percentage point in one environmental ledger.',
  ledgers: ['soilCover', 'freshwaterQuantity', 'freshwaterQuality', 'wetlandReefHabitat', 'renewableBiomass', 'arcaneStability'],
  decisionInputs: ['innateMigrationPattern', 'personallyRetainedMemory', 'actuallyReceivedInformation', 'currentLocalPerception'],
  forbiddenDecisionInputs: ['hiddenDestinationCapacity', 'unobservedIncomingGroups', 'globalHabitatRanking', 'futureResourceTruth'],
  destinationCapacityReservations: false,
  guaranteesSuccessfulArrival: false,
  wholePopulationTeleport: false,
  localReactionsRemainResponsive: true,
  migrationModes: [
    ['instinctive', 'Follow the inherited seasonal route and traditional destination, with biologically supported group variation.', 'Do not change a traditional destination because hidden present/future carrying capacity, competitors or damage make it unsuitable. Instinct is a route tendency, not remote sensing.'],
    ['forcedDispersal', 'A nonmigratory displaced group explores essentially randomly, with direction influenced only by immediate senses and actual traversability as encountered.', 'No global habitat search, omniscient safe path, distant food scent without a real signal, or survival guarantee. A randomly chosen destination may also fail.'],
    ['informed', 'Where cognition permits, use personally learned routes, remembered sites or genuinely received information.', 'Record whose knowledge it is, its source/date and uncertainty. It can be stale or wrong; intelligence alone grants no map, species-wide knowledge or privileged capacity forecast.']
  ].map(([id, choice, limits]) => ({ id, choice, limits })),
  rules: [
    ['Rate accounting', 'Keep separate nurturing and destruction rates per individual per game day in each ledger, including both effects for neutral creatures. Convert using the actual game-calendar month duration, not an assumed thirty-day month. Rates are throughput ceilings with normal rest already included, not free performed work. Numeric initial balance coefficients for all 36 entries are published below and in the workbook; C owns consumed implementation and further calibration, not a new prompt. Earlier sample rates are illustrative starting values, not proof of finalized gameplay balance.'],
    ['Monthly planning', 'Once per game month, assess actual environmental stocks for consequence accounting and produce finite activity budgets plus group departure schedules. Decision policy receives only the group’s instincts, actual memory, received information and local perception; private ecological truth is not supplied as an animal belief. A regional plan aggregates independent group intentions, not a coordinated species-wide meeting.'],
    ['Gradual effects', 'Do not apply the monthly forecast upfront or interpolate toward a guaranteed final state. Accrue only actually supported work/consumption over elapsed time and each group’s actual local residence; divide points by the affected hectares for condition-point change. Use cached piecewise rates and scheduled departure/arrival/resource-depletion boundaries, evaluated lazily when state is needed, rather than per-frame per-creature planning. Clamp effects to actual stocks/capacity without hiding the unmet needs.'],
    ['Group movement', 'Stagger departures throughout the month and use actual paths, travel time and compatible medium as encountered. Use viable herd fragments, family units, solitary individuals or supported colony divisions, never arbitrary splitting of every species. Retain original identities and integer membership, with no duplicated parent/group bodies. Source consumption changes on actual departure; destination consumption starts on actual arrival; transit feeding, damage and losses belong to actual route locations. Unfinished travel carries into later months without rerolling or teleportation.'],
    ['No invisible traffic controller', 'Do not reserve unknown destination capacity or distribute groups optimally using hidden food, incoming migrations or future conditions. Independent groups may converge, overcrowd and compete. Physical carrying capacity constrains real consequences, not decisions unless the group has actually obtained relevant information. Initial viability validation remains a generator check, not a protective migration oracle or a promise of continuing balance.'],
    ['Discovery and failure', 'On arrival or a local encounter, update only what that group actually perceives. A depleted traditional destination may cause starvation, conflict or a second departure into another unsuitable region. Forced dispersal may fail repeatedly. Continued travel consumes finite supplies/effort; hunger, injury and deaths happen during the month rather than waiting for the next planning pass. Arrival never repairs habitat or guarantees a meal.'],
    ['Interruptions and local reactions', 'Combat, immediate danger, local needs and existing creature AI remain responsive. A killed nurturer, burned food source, blocked route or discovered shortage invalidates affected unperformed work immediately; settle earned effects to the event time and adjust only affected budgets/groups. Do not replan all regions. A private change at an unseen destination does not cancel an instinctive departure or reveal itself to the group; its physical effects apply when relevant, and a new choice needs actual observation. No backfill or unearned restoration after interruption.'],
    ['Persistence and evidence', 'Save month boundaries, last-applied times, remaining paid/available budgets, deterministic departure choices, original members, transit progress and source-dated group knowledge. Repeated reads, reloads and continued imports cannot double-apply effects, reroll a bad destination or refill food; splitting elapsed time at event boundaries must preserve the same outcome. Only legitimate observed/received migration evidence reaches the player. Exhaustion still needs actual losses/damage, not a pessimistic monthly forecast.']
  ]
};

const rules = [
  ['Status and scope', `${STATUS}. All 36 current catalog entries receive a default nurturing, destroying or neutral disposition. The 24 strategic species retain their canonical IDs, names, size, intelligence, locomotion, diet, food-web niche, social pattern and habitat affinities. Exact gameplay rates/footprints are calibrated and tested inside B/C, not new prompts. No new species, production recipes, research tiers or unlisted powers are authorized.`],
  ['Meaning', 'Disposition describes usual net environmental effect at viable density, not morality, friendliness, combat threat, aspect, religion or food-web niche. Neutral is not zero impact. Activities, variants, density, season and injury determine realized impact; humans have no exemption. Nurturers may be dangerous predators and destroyers need not be evil.'],
  ['Other forms', 'Lore-confirmed dogs have a neutral baseline; no new dog actor/recipe/population is introduced. Divine/descended/avatar states, rebodied scientists and receiving bodies are not new species: use the actual base body, activities and finite effects, not a second ecological population. Generic implied fauna are not new catalog entries.'],
  ['Agency and antagonism', 'Edges below describe predation, competition, territorial defense or restorative opposition, not two universal allied factions. No automatic communication, orders, loyalty, holy war or shared knowledge. Slimes never communicate/cooperate. Soulless bodies have no initiative or self-care; passive biological filtering/decomposition still requires actual maintained resources. A soul does not grant consent, skill or speech.'],
  ['Finite local ledgers', 'Keep separate soil fertility/cover, freshwater quantity/quality, wetland/reef habitat, renewable food-web biomass and arcane stability accounts. Per seasonal window, each ordinary region needs effective nurturing plus natural renewal sufficient for sustained destructive pressure and ordinary consumption. Start/end buffers must remain viable through the seasonal minimum, not just average annually. No reef credit offsets inland poison; finite ore/geological material is not renewed by generic nurture.'],
  ['Effective capacity', 'Compute from actual conserved bodies/colony members, density, age, injury, stage, season, resources, reach and time. Charge feeding, fighting, travel and restoration to the same finite budget; no double-spending. Require viable antagonistic matchups/control of destroyer recruitment and protection of renewal sites, not equal headcounts. Neutral consumption/damage and positive destroyer byproducts both count. populationIndex is an abundance index, not animal count; devotional units measure soul organization, not labor/combat/restoration.'],
  ['Geography', 'Every credited counter must share reachable habitat or an actually adjoining traversable ecotone and appropriate air/water/ground medium. Preferred biome lists are affinities, not hard walls. A species-level edge is not proof two actual populations meet. Shared population ranges, seasonal presence, source identity and travel limits must support local coverage; random relationship-degree/display caps cannot silently discard required ecological defenses. Untouched deserts, polar regions and null zones can be healthy without lush cover or a nurturer army.'],
  ['Generation and history', 'Allocate feasible initial habitat/seasonal budgets and viable densities before causal history, then simulate consequences. Every strategic species still exists somewhere in every world; do not delete a hard-to-balance species. Core laboratory families have no automatically allocated wild population and cannot plug a missing regional budget. Reject/repair an infeasible initial allocation within generation, not by relabeling it exhausted, spawning rescuers or granting unsupported powers. Pristine means before city pressure, not before all natural conflict: genuinely simulated pre-city defeat may already leave exhausted territory.'],
  ['Exhausted territories', 'Exhaustion requires actual locally defeated/displaced nurturers or lost renewal sites, a causal destructive-pressure history and accumulated damage that consumes viable environmental buffers. Record who/what was lost, when, where, the affected ledgers and surviving populations. A bad seed, absent data, natural desert, winter, temporary damage or a dangerous human encounter is not evidence. Remaining life is possible; destroyers may then starve, decline or migrate rather than gain unlimited food. No worldwide headcount can certify a locally failing region.'],
  ['Living consequences and recovery', 'Healthy balance is a starting viability constraint, not permanent protection. War, beast rivalry, player extraction and killing nurturers may cause decline and exhaustion. Recovery needs real surviving/recolonizing sources, seeds/substrate, water/nutrients, viable access and elapsed work/time; vitrified soil may remain damaged long after a battle. No automatic respawn, reserve refill, magical replenishment of ore or fresh souls/life. Conserved migration may create waves but need not put every city on a migration path.'],
  ['Knowledge and persistence', 'Private population budgets and exhausted causes are not an omniscient public census, conservation certificate or domination proof. Only actually acquired dated observations/reports enter player knowledge; uncertainty/receipt date remain separate from truth. Loss, partial work, wounds, spent reserves, population membership and causal recovery survive saves/continued imports. Canonical world history remains immutable; mutable play belongs to its run branch. Irreversible death stops run work under existing soul-beacon rules.'],
  ['Carrion Lantern', 'A biological wind-dependent aerostat/scavenger, not a dead soul. Real carrion supplies finite corpse-light substrate; damage affects buoyancy. Light can create uncertain sensory cues for vulnerable injured/exhausted observers only within actual visibility. It cannot force player movement, fake a factual report, steal souls, resurrect, act as a soul beacon or add an explosive-gas attack.'],
  ['Preserved consumers', 'Rimefang, Gravebloom Elk and Mirror Ape retain completed grounded combat, existing perception and injuries, climbing, individual territorial compacts and the paid one-observation Soul Lash consumer. The authored cold/bloom extensions here remain C work where not already consumed. One contact group, individual defeat or treaty is never an entire population outcome.']
];
const packages = [
  ['A — this design deliverable', 'Freeze the 36 classifications, 24 biology/capability rows, directed antagonisms and shared rules below; publish spreadsheet/reference parity and focused contract checks. Complete on delivery; no runtime balance claim.'],
  ['B — bodies and reach', 'Consume all 24 bodies/senses with actual size/mass/occupancy/anatomy, flight/levitation, swimming/drifting/amphibious travel, burrowing, colonies/swarms, colossal clearance, fatigue, persistent injury and habitat/medium/season constraints. Retain grounded/climbing consumers; model representative physical encounters and catalog-wide coverage.'],
  ['C — abilities and behavior', 'Consume every listed strategic capability and its finite budgets/counters, including Carrion light, restoration, predation/recruitment control and directed antagonisms. Calibrate separate per-individual daily rates per ledger; predation changes actual destroyer pressure rather than awarding duplicate imaginary restoration. Apply the monthly knowledge-limited decision policy while keeping local reactions responsive. Actual agency, perception, resource expenditure, interruption and persistence apply; existing core creature abilities are reused, not rebuilt. No generic role label may substitute for performed behavior.'],
  ['D — populations, environments and outcomes', 'Conserve original population/member accounts; implement local seasonal maintenance and matchup validation, causal defeat/exhaustion, migration/decline and conditional recovery in pre-run history and run branches. Plan once per game month, accrue supported effects gradually and conserve staggered migrating groups/transit across months. No invisible destination-capacity reservations or hidden-truth guidance. Produce real military/nonmilitary outcomes and acquired dated observations for existing 3.35d-D/E. Test healthy, boundary, defeat, starvation, recovery, monthly timing, failed/overcrowded arrivals, knowledge-isolated choices, interrupted work, save/import and independent-restart cases. Close 3.38 here; no additional species prompts or certification gate.']
];

function adversaries(id) {
  return antagonisms.filter(e => e.nurturer === id || e.destroyer === id).map(e => {
    const other = rows.find(r => r.id === (e.nurturer === id ? e.destroyer : e.nurturer));
    return `${other.name}: ${e.mechanism} [${e.id}; ${e.geography}: ${e.habitat}]`;
  }).join(' / ') || 'No fixed nurturing–destroying edge; ordinary food-web relations and actual behavior still apply.';
}
const cell = text => String(text).replace(/\|/g, '\\|').replace(/\n/g, ' ');
const table = (head, data) => [head, head.map(() => '---'), ...data].map(r => `| ${r.map(cell).join(' | ')} |`).join('\n');
function renderReference() {
  return '# Creature biology and ecological capability matrix\n\n' +
    '> Approved #3.38-A design, 2026-11-12. **Not a claim of runtime implementation.**\n\n' +
    'This developer reference is generated from `scripts/creature-ecology-design.js`. Runtime source definitions remain authoritative for implemented behavior; B–D below own the remaining implementation. The matrix closes A without adding queue entries.\n\n' +
    '## Shared ecological contract\n\n' + rules.map(([name, text]) => `- **${name}.** ${text}`).join('\n') + '\n\n' +
    '## Monthly ecology and knowledge-limited migration\n\n' +
    'Approved clarification: monthly strategic planning with gradual execution, not monthly-only local reactions. This remains design, not an implemented planner.\n\n' +
    `${monthlyEcology.pointDefinition} Daily rate units: \`${monthlyEcology.rateUnit}\`. Ledgers: ${monthlyEcology.ledgers.join(', ')}. Physical stock/resource requirements still apply; points do not create matter or cross-cancel different ledgers.\n\n` +
    'For each ledger, accrued points = natural renewal + performed nurturing − performed destruction − other losses, integrated over actual elapsed residence/activity. Condition-point change = accrued points / affected hectares. For example, a fully supported constant 60 nurturing + 10 renewal − 40 destruction points/day over five elapsed days gives 150 points, or +1.5 condition points across 100 affected hectares; the rest of the month is not yet credited. Per-individual seasonal health/supply/activity limits share actual budgets; count neither an individual in two places nor rest twice. Predation/recruitment control changes real destructive capacity rather than also granting unperformed restoration.\n\n' +
    monthlyEcology.rules.map(([name, text]) => `- **${name}.** ${text}`).join('\n') + '\n\n' +
    table(['Migration decision mode', 'Permitted choice', 'Knowledge / failure boundary'], monthlyEcology.migrationModes.map(mode => [mode.id, mode.choice, mode.limits])) + '\n\n' +
    '## Numeric ecological rates — all 36 entries\n\n' +
    '**Initial authored balance values, not measured or live-game rates.** Each cell is `nurturing / destruction` in ecological points per individual per game day, including normal rest. One point changes one affected hectare by one percentage point in that ledger. The spreadsheet contains separate real numeric cells for each side. Zero is an explicit negligible/no direct baseline in these six ledgers, not missing data or a claim the creature has no other costs. Do not sum unlike ledgers.\n\n' +
    'Values are potential ceilings for the stated reference body/counting basis, not unconditional grants. Actual maturity, health, supply, habitat, season, working time and co-located finite stocks constrain achieved effects. Shared towers/furnaces/choirs and existing food harvesting or damage events are accounted once, never in addition to a duplicate full baseline. Traits, activity and engineered variants may override channels. Arcane stability is not stored mana quantity, and freshwater quantity means locally usable water, not molecular water creation/destruction. Airborne transfers and finite mineral depletion remain physical accounts outside these six rates. Predator control reduces actual future destructive pressure, not a duplicate direct restoration award. No ecological equilibrium or runtime adoption is certified by these initial numbers.\n\n' +
    table(['Creature', 'Counting basis', ...rateLedgers.map(([, label]) => `${label} N / D`), 'Limits / initial calibration'], rows.map(row => {
      const p = rateProfileById.get(row.id);
      return [row.name, p.basis, ...rateLedgers.map((_, i) => `${p.nurturing[i]} / ${p.destruction[i]}`), p.notes];
    })) + '\n\n' +
    '## Catalog classifications — 36 current entries\n\n' + table(['Creature / stable ID', 'Default environmental disposition', 'Net effect / qualification'], rows.map(r => [`${r.name} (${r.id})`, r.role, r.impact])) + '\n\n' +
    '## Existing core families — retain current consumers\n\n' + table(['Creature', 'Body / sensing', 'Finite budget', 'Capability / boundary'], rows.filter(r => !r.id.startsWith('beast:')).map(r => [r.name, `${r.body}; ${r.senses}`, r.budgets, `${r.capability}. ${r.limits}`])) + '\n\n' +
    '## Fixed strategic biology — 24 species\n\n' +
    'Habitat codes below are existing preferred biomes, not new hard exclusion masks. Food-web niche is distinct from nurturing/destroying/neutral disposition. All named senses require a real signal/medium; none grants omniscient map knowledge. No extra power may be inferred from a body or aspect label.\n\n' +
    table(['Species', 'Canonical scale / cognition / social / diet / food-web niche / habitat', 'Body / locomotion', 'Senses', 'Finite budget', 'Authored capability / meaningful limits'], rows.filter(r => r.id.startsWith('beast:')).map(r => {
      const s = BEAST_SPECIES.find(s => s.id === r.id);
      return [r.name, `${s.sizeBand}; ${s.intelligenceBand}; ${s.socialPattern}; ${s.diet}; ${s.ecologicalRole}; ${s.realm}: ${s.biomeCodes.join(', ')}`, `${r.body}; ${s.movementModes.join(', ')}`, r.senses, r.budgets, `${r.capability}. ${r.limits}`];
    })) + '\n\n' +
    '## Directed ecological antagonisms\n\n' +
    'Shared means overlapping preferred biomes are possible, not guaranteed population contact. Ecotone pairs name the nurturer side first. Local core-family edges require an actual supplied body/site, not an invented strategic population. Destructive actors may attack nurturers in return; the arrow identifies opposing environmental functions, not guaranteed combat victory.\n\n' +
    table(['Edge', 'Nurturer → destroyer', 'Required setting', 'Performed opposition', 'Failure / scope limit'], antagonisms.map(e => [e.id, `${rows.find(r => r.id === e.nurturer).name} → ${rows.find(r => r.id === e.destroyer).name}`, `${e.geography}: ${e.habitat}`, e.mechanism, e.limits])) + '\n\n' +
    '## Fixed acceptance ownership — no additional prompts\n\n' + table(['Existing package', 'Completion responsibility'], packages) + '\n';
}
module.exports = { STATUS, rows, antagonisms, rateLedgers, rateProfiles, rateProfileById, rateCells, monthlyEcology, rules, packages, adversaries, renderReference };
